#!/usr/bin/env bash
# Autogenerated test: runs inside a container built from each compatibility image with antigravity installed.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib

readonly INITIALIZE="/usr/local/share/antigravity-feature/initialize"
readonly STATE_DIR="/var/lib/antigravity"
readonly MANIFEST_URL="https://antigravity-cli-auto-updater-974169037036.us-central1.run.app/manifests"

# The version the current manifest names when the test runs; a release between build and test fails once.
case "$(uname -m)" in
  x86_64) platform=linux_amd64 ;;
  aarch64) platform=linux_arm64 ;;
esac
current="$(curl --fail --silent --show-error --location "${MANIFEST_URL}/${platform}.json" | jq -r .version)"

default_path() {
  [[ "$(env -i PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin sh -c 'command -v agy')" \
    == /usr/local/bin/agy ]]
}
links_to() {
  [[ -L "$1" && "$(readlink -f "$1")" == "$2" ]]
}
# The exact line `agy install` appends; literal on purpose.
# shellcheck disable=SC2016
profiles_untouched() {
  ! grep -qsF 'export PATH="$HOME/.local/bin:$PATH"' "${HOME}/.bashrc" "${HOME}/.profile"
}
private_root() {
  [[ "$(stat -c %u:%a "${STATE_DIR}")" == "$(id -u):700" ]]
}

check "agy runs as the remote user and reports the manifest's current version" test "$(agy --version)" = "${current}"
check "agy resolves from the default PATH" default_path
check "the executable lives outside the state volume" test -x /usr/local/share/antigravity/agy
check "shell profiles carry no PATH export from agy install" profiles_untouched
check "upstream self-updates are disabled by default" test "${AGY_CLI_DISABLE_AUTO_UPDATE-}" = true
check "creation-time initialization succeeds without credentials" "${INITIALIZE}"
check "the CLI data directory links into the volume" links_to "${HOME}/.gemini/antigravity-cli" "${STATE_DIR}/cli"
check "the global configuration directory links into the volume" \
  links_to "${HOME}/.gemini/config" "${STATE_DIR}/gemini-config"
check "the plugin-secret directory links into the volume" \
  links_to "${HOME}/.config/antigravity" "${STATE_DIR}/plugin-secrets"
check "the state root belongs privately to the remote user" private_root
check "the whole .gemini tree is not linked" test ! -L "${HOME}/.gemini"
check "installation stores no login token" test ! -e "${STATE_DIR}/cli/antigravity-oauth-token"
check "installation stores no plugin secrets" test ! -e "${STATE_DIR}/plugin-secrets/plugin-secrets.json"
check "repeated initialization reuses the links" "${INITIALIZE}"

reportResults
